// Onboarding state lives in THIS workflow's static data (sessions keyed channel:thread). Deterministic steps here;
// the LLM is only used to understand a free-text answer (one cheap call per answer).
const Q = [{"id": "q1", "title": "Business", "text": "What's the business called, and what do you sell?"}, {"id": "q2", "title": "Location and customers", "text": "Which city or area are you in, and who are your customers there?"}, {"id": "q3", "title": "90-day goals", "text": "What are your main goals for the next 90 days? (more leads, followers, a launch, anything)"}, {"id": "q4", "title": "Ideal customer / audience", "text": "Who is your ideal customer or audience, the people these posts should reach?"}, {"id": "q5", "title": "Brand voice", "text": "Give me 3 words for your brand voice, and paste (or describe) an example post you like."}, {"id": "q6", "title": "Platforms and links", "text": "Which platforms do you use? Please share the links: website, X, LinkedIn, Facebook, Instagram, anything else."}, {"id": "q7", "title": "Topics to post / avoid", "text": "What topics should we post about, and is there anything we should never post about?"}, {"id": "q8", "title": "Competitors / admired accounts", "text": "Any competitors or accounts you admire? Handles or links are perfect."}, {"id": "q9", "title": "Approval preference", "text": "How do you want approvals: approve every post yourself, or let routine stuff (like scheduled tips) go out automatically?"}, {"id": "q10", "title": "Contact and working hours", "text": "Last one: best way to reach you, and your working hours?"}];
const t = $('When called').first().json;
const st = $getWorkflowStaticData('global'); st.sessions = st.sessions || {};
const dry = t.dry_run === true || t.dry_run === 'true';
const thread = t.thread_ts || t.ts;
const key = (dry ? 'dry:' : '') + (t.channel || '') + ':' + thread;
const now = Date.now() / 1000;
for (const [k, v] of Object.entries(st.sessions)) if (now - (v.updated || 0) > 14 * 86400) delete st.sessions[k];
const mode = String(t.mode || 'answer'), text = String(t.text || '').trim();
const base = { key, dry, client: t.client || 'client1', channel: t.channel || 'C0000000001', thread_ts: thread, ts: t.ts || '', mode, text };
const fin = reply => [{ json: { ...base, final: true, needs_llm: false, reply } }];
if (mode === 'reset') { for (const k of Object.keys(st.sessions)) if (k.startsWith('dry:')) delete st.sessions[k]; return fin('(dry-run sessions cleared)'); }
let s = st.sessions[key];
if (mode === 'start') {
  st.sessions[key] = { client: base.client, answers: {}, skipped: [], current: 'q1', status: 'active', started: now, updated: now };
  return fin(`Hi! Let's set things up so I post and engage the way you like. About ${Q.length} quick questions, one at a time, right here in this thread. Say 'skip' to skip one, or 'stop onboarding' to stop.\n\n*1/${Q.length}* ${Q[0].text}`);
}
if (!s) return fin("I don't have an onboarding open in this thread. Say 'start onboarding' in the channel to begin.");
if (mode === 'cancel' || /^(stop|cancel) onboarding\b/i.test(text)) { delete st.sessions[key]; return fin("Onboarding stopped. Answers given so far were not saved. Say 'start onboarding' to begin again."); }
s.updated = now;
const nextQ = () => Q.find(q => !(q.id in s.answers) && !s.skipped.includes(q.id));
const qtext = id => (Q.find(q => q.id === id) || {}).text;
if (s.status !== 'active') {
  if (/^(no|nope|nothing|all good|looks good|lgtm|that'?s (it|all)|perfect|fine|ok(ay)?|done)\b/i.test(text)) { s.status = 'closed'; return fin("Great, it's all in the client notes. I'll use it from now on. You can add more anytime with 'remember: ...'."); }
  return [{ json: { ...base, final: false, needs_llm: true, phase: 'fix', prompt:
    `An onboarding interview for a social media client is finished. Questions: ${JSON.stringify(Q.map(q => ({ id: q.id, q: q.text })))}\nSaved answers: ${JSON.stringify(s.answers)}\nThe client now writes:\n<<<${text}>>>\nIf this corrects or adds to any answer, return the FULL corrected answer text for those ids. Keep their own words, be concise, never invent.\nReturn ONLY JSON: {"updates": {"<id>": "<corrected answer>"}} (empty updates if it is not a correction).` } }];
}
if (/^(skip|pass|next|n\/a|not sure|later|no idea)\b/i.test(text) && text.length < 30) {
  s.skipped.push(s.current);
  return [{ json: { ...base, final: false, needs_llm: false, phase: 'answer', skipped: true } }];
}
return [{ json: { ...base, final: false, needs_llm: true, phase: 'answer', prompt:
  `You run a friendly onboarding interview (Slack thread) for a small-business social media client.\nQuestions in order: ${JSON.stringify(Q.map(q => ({ id: q.id, q: q.text })))}\nAnswers so far: ${JSON.stringify(s.answers)}\nSkipped: ${JSON.stringify(s.skipped)}\nCurrent question: ${s.current} (${qtext(s.current)})\nThe client's reply:\n<<<${text}>>>\n` +
  `Return ONLY JSON: {"updates": {"<id>": "<concise faithful summary in their words>"}, "next_id": "<first question id in order still unanswered and not skipped after your updates, or empty if none>", "next_question": "<short warm acknowledgement of what they said (max 12 words) + that next question, adapted to what you already know; exactly one question>"}.\n` +
  `Always include the current question in updates (if they did not really answer it, store what they said). Use details from earlier answers too (e.g. a city or customer type they already mentioned) instead of writing 'not specified'. Add other ids ONLY if this reply clearly answers them. Never invent facts, links or numbers. Plain friendly English, no emojis.` } }];

const Q = [{"id": "q1", "title": "Business", "text": "What's the business called, and what do you sell?"}, {"id": "q2", "title": "Location and customers", "text": "Which city or area are you in, and who are your customers there?"}, {"id": "q3", "title": "90-day goals", "text": "What are your main goals for the next 90 days? (more leads, followers, a launch, anything)"}, {"id": "q4", "title": "Ideal customer / audience", "text": "Who is your ideal customer or audience, the people these posts should reach?"}, {"id": "q5", "title": "Brand voice", "text": "Give me 3 words for your brand voice, and paste (or describe) an example post you like."}, {"id": "q6", "title": "Platforms and links", "text": "Which platforms do you use? Please share the links: website, X, LinkedIn, Facebook, Instagram, anything else."}, {"id": "q7", "title": "Topics to post / avoid", "text": "What topics should we post about, and is there anything we should never post about?"}, {"id": "q8", "title": "Competitors / admired accounts", "text": "Any competitors or accounts you admire? Handles or links are perfect."}, {"id": "q9", "title": "Approval preference", "text": "How do you want approvals: approve every post yourself, or let routine stuff (like scheduled tips) go out automatically?"}, {"id": "q10", "title": "Contact and working hours", "text": "Last one: best way to reach you, and your working hours?"}];
const S = $('Step').first().json;
if (S.final) return [{ json: { ...S, block: null } }];
const st = $getWorkflowStaticData('global'); const s = st.sessions[S.key];
if (!s) return [{ json: { ...S, reply: 'Onboarding session not found.', block: null } }];
let obj = {};
if (S.needs_llm) { const raw = String($json.text || ''); const m = raw.match(/\{[\s\S]*\}/); if (m) { try { obj = JSON.parse(m[0]); } catch (e) { obj = {}; } } }
const upd = (obj && typeof obj.updates === 'object' && obj.updates) || {};
const ids = Q.map(q => q.id);
if (S.phase === 'answer' && !S.skipped && !Object.keys(upd).length) upd[s.current] = S.text;   // LLM failed -> keep the raw answer
const changed = [];
for (const [k, v] of Object.entries(upd)) if (ids.includes(k) && String(v || '').trim()) { s.answers[k] = String(v).trim().slice(0, 800); s.skipped = s.skipped.filter(x => x !== k); changed.push(k); }
const when = $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm');
const buildBlock = () => `## Onboarding answers (Slack interview, updated ${when} IST)\n` + Q.map(q => `### ${q.title}\n${s.answers[q.id] || '_(skipped)_'}`).join('\n\n');
const summary = () => Q.map(q => `• *${q.title}:* ${(s.answers[q.id] || '_skipped_').replace(/\s+/g, ' ').slice(0, 140)}`).join('\n');
if (S.phase === 'fix') {
  if (!changed.length) return [{ json: { ...S, reply: "Got it. I didn't change anything in the notes. Tell me what to fix, or say 'looks good'.", block: null } }];
  return [{ json: { ...S, reply: `Updated in the client notes: ${changed.map(k => Q.find(q => q.id === k).title).join(', ')}.\nAnything else to fix?`, block: buildBlock() } }];
}
const n = Q.find(q => !(q.id in s.answers) && !s.skipped.includes(q.id));
if (n) {
  s.current = n.id;
  const pos = Q.indexOf(n) + 1;
  const ask = (obj.next_id === n.id && obj.next_question) ? String(obj.next_question).slice(0, 400) : (S.skipped ? 'No problem, skipped. ' : 'Thanks! ') + n.text;
  return [{ json: { ...S, reply: `*${pos}/${Q.length}* ${ask}`, block: null } }];
}
s.status = 'done'; s.current = null;
return [{ json: { ...S, block: buildBlock(), reply: `Thanks, that's everything! Here's what I saved to the client notes:\n${summary()}\n\nAnything to fix? Reply here with corrections, or say 'looks good'.` } }];

const a = $('Apply answer').first().json, h = $json || {};
const slack = { channel: a.channel, thread_ts: a.thread_ts, text: String(a.reply || '').slice(0, 3900), unfurl_links: false, unfurl_media: false };
if (a.block && h.ok === false) slack.text += '\n:warning: (saving to notes.md failed: ' + String(h.error || '').slice(0, 120) + ')';
return [{ json: { dry: a.dry, has_text: !!a.reply, slack, notes: h, block: a.block, state: ($getWorkflowStaticData('global').sessions || {})[a.key] || null,
                  receipt: { channel: a.channel, ts: a.ts, ok: true, note: '', thread_ts: a.thread_ts } } }];
